package com.nexttv;
import android.app.*;import android.content.*;import android.os.*;import android.view.KeyEvent;import android.view.accessibility.AccessibilityNodeInfo;
public class StyleNavigationInstrumentation extends com.nexttv.support.NextTvInstrumentation {
 private Activity activity;private int passed;private final StringBuilder results=new StringBuilder();
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}

 protected void launch()throws Exception{activity=startActivitySync(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));text("频道分类：");SystemClock.sleep(2300);}
 private void closeEditor()throws Exception{key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(400);if(tree().contains("保存"))key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(250);}
 protected void pass(String name){passed++;results.append("PASS ").append(name).append('\n');Bundle b=new Bundle();b.putString("stream","PASS "+name+"\n");sendStatus(0,b);}


 private void reopen(){try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("am start -a android.intent.action.MAIN -c android.intent.category.LAUNCHER -f 0x10200000 -n com.nexttv/com.nexttv.core.tv.TvActivity")){java.io.FileInputStream input=new java.io.FileInputStream(fd.getFileDescriptor());byte[] buffer=new byte[1024];while(input.read(buffer)>=0){}}catch(Exception e){throw new RuntimeException(e);}}
 private void shot(String name)throws Exception{android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getFilesDir(),"fix13-"+name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}

 private void export(String name,byte[] data,String mime,String suffix)throws Exception{String file="nexttv-audit-"+name+"-"+SystemClock.uptimeMillis()+suffix;android.content.ContentValues v=new android.content.ContentValues();v.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,file);v.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,mime);v.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Download/NextTVAudit");android.net.Uri uri=getTargetContext().getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);try(java.io.OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){out.write(data);}Bundle b=new Bundle();b.putString("stream","EXPORT "+file+"\n");sendStatus(0,b);}
 private String nodes(AccessibilityNodeInfo n){if(n==null)return "";android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);String t=n.getText()==null?"":n.getText().toString();String d=n.getContentDescription()==null?"":n.getContentDescription().toString();StringBuilder b=new StringBuilder();if(!t.isEmpty()||!d.isEmpty()||n.isFocusable())b.append("text=").append(t).append(" desc=").append(d).append(" selected=").append(n.isSelected()).append(" focus=").append(n.isFocused()).append(" focusable=").append(n.isFocusable()).append(" click=").append(n.isClickable()).append(" bounds=").append(r).append('\n');for(int i=0;i<n.getChildCount();i++)b.append(nodes(n.getChild(i)));return b.toString();}
 private void record(String name)throws Exception{SystemClock.sleep(350);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,bytes);image.recycle();export(name,bytes.toByteArray(),"image/png",".png");export(name,nodes(getUiAutomation().getRootInActiveWindow()).getBytes(java.nio.charset.StandardCharsets.UTF_8),"text/plain",".txt");}
 private void desc(String description)throws Exception{AccessibilityNodeInfo n=getUiAutomation().getRootInActiveWindow();java.util.ArrayDeque<AccessibilityNodeInfo> q=new java.util.ArrayDeque<>();q.add(n);while(!q.isEmpty()){n=q.removeFirst();if(description.contentEquals(n.getContentDescription()==null?"":n.getContentDescription())){while(!n.isClickable())n=n.getParent();n.performAction(AccessibilityNodeInfo.ACTION_CLICK);SystemClock.sleep(300);return;}for(int i=0;i<n.getChildCount();i++)if(n.getChild(i)!=null)q.add(n.getChild(i));}throw new IllegalStateException("Missing description "+description);}
 private android.content.SharedPreferences prefs;private java.util.Map<String,?> saved;
 private void restore(){if(saved==null)return;if(activity!=null&&!activity.isFinishing()){runOnMainSync(()->activity.finish());waitForIdleSync();}android.content.SharedPreferences.Editor e=prefs.edit().clear();for(java.util.Map.Entry<String,?> entry:saved.entrySet()){String k=entry.getKey();Object v=entry.getValue();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof java.util.Set)e.putStringSet(k,(java.util.Set<String>)v);}e.commit();saved=null;}

 private void sourceRow()throws Exception{java.util.ArrayDeque<AccessibilityNodeInfo> q=new java.util.ArrayDeque<>();q.add(getUiAutomation().getRootInActiveWindow());while(!q.isEmpty()){AccessibilityNodeInfo n=q.removeFirst();if(n.isClickable()&&tree(n).contains("个频道")){n.performAction(AccessibilityNodeInfo.ACTION_CLICK);SystemClock.sleep(250);return;}for(int i=0;i<n.getChildCount();i++)if(n.getChild(i)!=null)q.add(n.getChild(i));}throw new IllegalStateException("Missing source row");}

 @Override public void onStart(){try{
  prefs=getTargetContext().getSharedPreferences("nexttv",0);saved=prefs.getAll();prefs.edit().putString("selected_group","").putBoolean("previews",false).putBoolean("auto_update",false).putBoolean("auto_update_epg",false).commit();launch();focus("CCTV1综合");for(int i=0;i<8;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_ESCAPE);await("channel Back directly to nav",()->focus().equals("频道"));record("node3-channel-return-nav");key(KeyEvent.KEYCODE_DPAD_DOWN);await("first channel control",()->focus().startsWith("频道分类："));key(KeyEvent.KEYCODE_DPAD_DOWN);await("first channel after reset",()->focus().contains("CCTV1综合"));pass("scrolled Channels → animated top + Channels nav → first control → first card");
  focus("收藏");key(KeyEvent.KEYCODE_DPAD_DOWN);await("favorites first control",()->(!focus().equals("收藏")||tree().contains("没有收藏频道")));key(KeyEvent.KEYCODE_ESCAPE);await("favorites Back to own nav",()->focus().equals("收藏"));key(KeyEvent.KEYCODE_DPAD_DOWN);await("favorites first control after reset",()->(!focus().equals("收藏")||tree().contains("没有收藏频道")));pass("Favorites Back and re-entry use the same own-menu/reset rule");
  focus("设置");key(KeyEvent.KEYCODE_DPAD_DOWN);await("settings first row",()->focus().contains("节目单地址"));for(int i=0;i<9;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_ESCAPE);await("settings Back to nav",()->focus().equals("设置"));SystemClock.sleep(500);key(KeyEvent.KEYCODE_DPAD_DOWN);await("settings reset to first row",()->focus().contains("节目单地址"));record("node3-settings-reset-first");key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_BACK);await("settings Back from next row",()->focus().equals("设置"));key(KeyEvent.KEYCODE_DPAD_DOWN);await("settings first row again",()->focus().contains("节目单地址"));pass("Settings Back clears previous row and next Down always starts at EPG address");
  for(int i=0;i<4;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);await("source row",()->focus().contains("管理播放源"));key(KeyEvent.KEYCODE_ENTER);key(KeyEvent.KEYCODE_ESCAPE);await("source parent row",()->focus().contains("管理播放源"));key(KeyEvent.KEYCODE_ESCAPE);await("parent then top",()->focus().equals("设置"));key(KeyEvent.KEYCODE_DPAD_DOWN);await("first row after source parent Back",()->focus().contains("节目单地址"));pass("source management preserves parent level, then top Back resets settings entry");
  focus("频道");for(int i=0;i<5;i++){key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_LEFT);key(KeyEvent.KEYCODE_DPAD_LEFT);}await("stable channel nav",()->focus().equals("频道"));record("node3-navigation-capsule");pass("repeated remote menu switching keeps one focused current page");restore();Bundle b=new Bundle();b.putString("stream",results+"Navigation consistency: "+passed+" groups passed\n");finish(Activity.RESULT_OK,b);
 }catch(Throwable t){restore();Bundle b=new Bundle();b.putString("stream",android.util.Log.getStackTraceString(t));finish(Activity.RESULT_CANCELED,b);}}
}
